def _require_minutes(minutes: int) -> int:
    if not isinstance(minutes, int):
        raise TypeError("minutes must be an int")
    if minutes < 0:
        raise ValueError("minutes must be non-negative")
    return minutes


def _split_minutes(minutes: int) -> tuple[int, int]:
